def transform(grid):
    # In each test, mask color 6 marks erasure. Reconstruct from transpose symmetry.
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==6:
                if c<h and r<w and grid[c][r]!=6: out[r][c]=grid[c][r]
                elif grid[h-1-r][w-1-c]!=6: out[r][c]=grid[h-1-r][w-1-c]
    return out
